def _format_lessons_for_injection(lessons: list[dict]) -> tuple[str, list[str]]:
    """
    教訓・セッションエントリのリストをプロンプト注入用にフォーマットする。
    表示も行い、(lessons_block, formatted_lines) を返す。
    """
    formatted_lines = []
    for e in lessons:
        e_type = e.get("type", "lesson")
        if e_type == "session":
            title    = e.get("title", "無題")
            summary  = e.get("summary", "")
            created  = _parse_dt(e.get("created_at", ""))
            days_ago = (datetime.now() - created).days
            line = f"[セッション: {title}] {summary} ({days_ago}日前)"
            formatted_lines.append(line[:150])
        else:
            text = e.get("lesson", "")
            line = f"[教訓] {_compress_lesson(text)}"
            formatted_lines.append(line[:100])
    for fl in formatted_lines[:5]:
        safe_print(C.mem(f"     • {fl}"), flush=True)
    lessons_block = "\n".join(formatted_lines[:5])
    return lessons_block, formatted_lines


def _extract_ps_status(result: str) -> str:
    """
    run_powershell の結果テキストからステータス行を抽出する。
    '[SUCCESS]' / '[FAILURE(ExitCode=N)]' / '[FAILURE(TIMEOUT)]' を返す。
    run_powershell を使っていないステップは空文字を返す。
    """
    for line in result.splitlines():
        line = line.strip()
        if line.startswith("[SUCCESS]") or line.startswith("[FAILURE"):
            return line
    return ""

