class WorkflowGraph:
    """
    PlanStep リストをグラフとして管理し、条件分岐・ジャンプ・共有ステートを制御する。

    エッジ遷移（on_failure / on_success）:
      "retry"       — リトライ（MAX_STEP_RETRY 回まで）
      "skip"        — スキップして次のステップへ
      "abort"       — ワークフロー全体を即座に中断
      "goto:<label>"— 指定ラベルのステップへジャンプ

    ループ防止:
      max_iterations > 0 のとき、同一ステップへの goto 回数が上限に達したら skip へ格下げ。
      未指定（0）の場合は安全上限 GOTO_HARD_LIMIT = 10 を適用。

    共有ステート:
      state dict にキー/値を保存し、各ステップのプロンプトへ自動注入する。
      ステップ結果内の [STATE: key=value] マーカーを自動パースして更新する。
    """

    GOTO_HARD_LIMIT = 10  # max_iterations=0 のときのハードリミット

    def __init__(self, steps: list[PlanStep]):
        self.steps = steps
        self.state: dict[str, str] = {}          # 共有ステート（スレッドセーフ書き込みは呼び出し元で制御）
        self._state_lock = threading.Lock()
        self._label_map: dict[str, int] = {      # label → step.index
            s.label: s.index for s in steps if s.label
        }
        self._goto_counts: dict[int, int] = {}   # step.index → goto された回数

    # ── 共有ステート ────────────────────────────────────────────

    def state_set(self, key: str, value: str) -> None:
        with self._state_lock:
            self.state[key] = value

    def state_get(self, key: str, default: str = "") -> str:
        return self.state.get(key, default)

    def state_as_text(self) -> str:
        """exec_prompt 注入用のテキスト表現"""
        if not self.state:
            return ""
        lines = "\n".join(f"  {k}: {v}" for k, v in self.state.items())
        return f"[共有ステート]\n{lines}"

    def parse_state_updates(self, result: str) -> None:
        """
        ステップ結果から [STATE: key=value] マーカーを検出して state を更新する。
        例: "[STATE: api_key=abc123]" → state["api_key"] = "abc123"
        """
        for m in re.finditer(r'\[STATE:\s*(\w+)\s*=\s*(.+?)\]', result):
            self.state_set(m.group(1).strip(), m.group(2).strip())

    # ── エッジ解決（共通ロジック） ──────────────────────────────

    def _resolve_directive(self, directive: str, step: PlanStep) -> tuple[str, Optional[int]]:
        """
        "retry" | "skip" | "abort" | "goto:<label>" を解釈して (action, goto_index) を返す。
        goto の場合はループカウンタをチェックし、上限超過なら "skip" に格下げ。
        """
        d = directive.strip().lower()
        if d in ("retry", ""):
            return "retry", None
        if d == "skip":
            return "skip", None
        if d == "abort":
            return "abort", None
        if d.startswith("goto:"):
            label = directive[5:].strip()
            idx = self._label_map.get(label)
            if idx is None:
                log.warning({"event": "workflow_goto_label_not_found", "label": label})
                return "skip", None
            # ループ上限チェック
            limit = step.max_iterations if step.max_iterations > 0 else self.GOTO_HARD_LIMIT
            count = self._goto_counts.get(step.index, 0) + 1
            if count > limit:
                safe_print(C.yellow(
                    f"  ⚠ Step {step.index} の goto ループが上限({limit}回)に達したためスキップ"
                ), flush=True)
                log.warning({"event": "workflow_goto_loop_limit",
                             "step": step.index, "limit": limit})
                return "skip", None
            self._goto_counts[step.index] = count
            return "goto", idx
        return "retry", None

    def resolve_failure(self, step: PlanStep) -> tuple[str, Optional[int]]:
        """失敗時の on_failure を解釈する"""
        return self._resolve_directive(step.on_failure, step)

    def resolve_success(self, step: PlanStep) -> tuple[str, Optional[int]]:
        """
        成功時の on_success を解釈する。
        空文字なら ("next", None) = 通常の次ステップへ進む。
        """
        if not step.on_success:
            return "next", None
        return self._resolve_directive(step.on_success, step)

    def summary(self) -> str:
        """実行後のステップ状態サマリー（ログ・表示用）"""
        return " → ".join(
            f"[{s.index}:{s.label or s.description[:20]} {s.status}]"
            for s in self.steps
        )

